/// Strang triangle quadrature rule of order p as a (4, npts) view.
pub fn strang(p: usize) -> ArrayView2<'static, f64> {
    let (rows, data): (usize, &'static [f64]) = match p {
        1 => (4, STRANG1.as_flattened()),
        2 => (4, STRANG2.as_flattened()),
        3 => (4, STRANG3.as_flattened()),
        4 => (4, STRANG4.as_flattened()),
        5 => (4, STRANG5.as_flattened()),
        6 => (4, STRANG6.as_flattened()),
        7 => (4, STRANG7.as_flattened()),
        8 => (4, STRANG8.as_flattened()),
        9 => (4, STRANG9.as_flattened()),
        10 => (4, STRANG10.as_flattened()),
        _ => panic!("No strang rule of order {p}"),
    };
    ArrayView2::from_shape((rows, data.len() / rows), data).unwrap()
}

